Series diarias de la cuenca
# Precipitación (PISCOp v3, 1981–2025) y temperatura (PISCO, 1981–2020)
# por subcuenca -&gt; cuenca: promedio ponderado por área
serie_cuenca &lt;- function(archivo, nombre) {
  read_csv(archivo) |&gt;
    pivot_longer(-Date, names_to = "subcuenca", values_to = "valor") |&gt;
    mutate(subcuenca = parse_number(subcuenca)) |&gt;
    left_join(areas, by = "subcuenca") |&gt;
    group_by(fecha = Date) |&gt;
    summarise({{ nombre }} := weighted.mean(valor, area_km2))
}

clima &lt;- serie_cuenca("data/pcp/Datos_pcp.csv",   pp) |&gt;
  left_join(serie_cuenca("data/temp/Datos_tmax.csv", tmax), by = "fecha") |&gt;
  left_join(serie_cuenca("data/temp/Datos_tmin.csv", tmin), by = "fecha")
#&gt;   fecha         pp  tmax  tmin
#&gt;   1981-01-01  6.40  14.5  2.14

Las llaves dobles alrededor de nombre y el operador := usan el nombre que le pasamos (pp, tmax, tmin) como nombre de la columna nueva.

Calcular los índices con summarise()
# Racha más larga de TRUE seguidos: rle() cuenta "corridas"
racha_max &lt;- function(condicion) {
  r &lt;- rle(condicion)
  max(c(0, r$lengths[r$values]))
}
racha_max(c(TRUE, TRUE, FALSE, TRUE, TRUE, TRUE))   #&gt; 3

indices_pp &lt;- clima |&gt;
  group_by(anio = year(fecha)) |&gt;
  summarise(PRCPTOT = sum(pp[pp &gt;= 1]),
            Rx1day  = max(pp),
            Rx5day  = max(zoo::rollsum(pp, 5)),
            CDD     = racha_max(pp &lt; 1),
            CWD     = racha_max(pp &gt;= 1))

indices_t &lt;- clima |&gt;
  filter(year(fecha) &lt;= 2020) |&gt;
  group_by(anio = year(fecha)) |&gt;
  summarise(TX = mean(tmax), TN = mean(tmin),
            FD = sum(tmin &lt; 0))                     # días con helada

Todos los casos con nest() y pmap()
corregir &lt;- function(o, m, variable) {
  m_ref  &lt;- m$valor[year(m$fecha) %in% ref]        # ajuste en 1981-2014
  ajuste &lt;- fitQmap(o$valor, m_ref, method = "QUANT",
                    wet.day = variable == "pp")
  tibble(fecha = m$fecha, valor = doQmap(m$valor, ajuste))  # aplica 1981-2050
}

cmip_qm &lt;- cmip |&gt;
  pivot_longer(c(pp, tmax, tmin), names_to = "variable", values_to = "valor") |&gt;
  mutate(mes = month(fecha)) |&gt;
  nest(m = c(fecha, valor)) |&gt;                     # 540 grupos
  left_join(obs_mes, by = c("subcuenca", "variable", "mes")) |&gt;
  mutate(cor = pmap(list(o, m, variable), corregir)) |&gt;
  select(modelo, subcuenca, variable, cor) |&gt;
  unnest(cor) |&gt;
  pivot_wider(names_from = variable, values_from = valor)

3 modelos × 5 subcuencas × 3 variables × 12 meses = 540 ajustes en ~20 segundos. Control: ningún día con Tmin ≥ Tmax.

Una función para simular cualquier clima

simular &lt;- function(forzantes, anios_warmup = 3) {
  f &lt;- forzantes |&gt;
    left_join(latitudes, by = "subcuenca") |&gt;
    mutate(etp = hargreaves(tmax, tmin, lat, fecha))
  # ... matrices de pp y etp con a_matriz() (columnas en el orden de griwrm)
  InputsModel &lt;- CreateInputsModel(griwrm, DatesR = fechas,
                                   Precip = a_matriz("pp"), PotEvap = a_matriz("etp"))
  n_warm &lt;- 365 * anios_warmup
  RunOptions &lt;- CreateRunOptions(InputsModel,
                                 IndPeriod_WarmUp = 1:n_warm,          # 1981-1983
                                 IndPeriod_Run = seq_along(fechas))    # desde 1981
  salida &lt;- RunModel(InputsModel, RunOptions, Param)
  tibble(fecha = fechas, q = attr(salida, "Qm3s")[["5"]])
}

q_qm &lt;- cmip_qm |&gt;
  nest(forzantes = -modelo) |&gt;              # un clima por modelo
  mutate(q = map(forzantes, simular)) |&gt;
  unnest(q)


La referencia empieza en 1981 y no hay años previos: se calienta con 1981–1983 y la corrida vuelve a empezar en 1981 con los almacenamientos ya cargados.

Caudal: cambio por tramo de río

q_nodos &lt;- cmip_qm |&gt;
  nest(forzantes = -modelo) |&gt;
  mutate(q = map(forzantes, \(f) simular(f, nodos = griwrm$id))) |&gt;
  unnest(q)                                  # caudal en los 5 nodos

El caudal responde más que la lluvia y no igual en todos los tramos: en el tramo 4 la lluvia sube +9 a +10 % (MIROC6, MPI) y el caudal +22 a +46 %. Con ACCESS-CM2 el tramo 2 pierde caudal (−4 %) porque la ETP (+6 %) crece más que la lluvia (+4 %).

Agregación: diaria → mensual
max_na &lt;- 3     # un mes es válido con 3 días sin dato como máximo

q_mensual &lt;- q_full |&gt;
  group_by(anio = year(fecha), mes = month(fecha)) |&gt;
  summarise(n_na = sum(is.na(q)),
            q    = mean(q, na.rm = TRUE),     # caudal: PROMEDIO
            .groups = "drop") |&gt;
  mutate(q = if_else(n_na &gt; max_na, NA, q))

pp_mensual &lt;- pp_full |&gt;
  group_by(anio = year(fecha), mes = month(fecha)) |&gt;
  summarise(n_na = sum(is.na(pp)),
            pp   = sum(pp, na.rm = TRUE),     # precipitación: SUMA
            .groups = "drop") |&gt;
  mutate(pp = if_else(n_na &gt; max_na, NA, pp))

